def separate_paren_groups(parenstring: str) -> List[str]:
    groups = []
    current = []
    depth = 0

    for ch in parenstring:
        if ch.isspace():
            continue

        if ch == '(':
            depth += 1
            current.append(ch)
        elif ch == ')':
            current.append(ch)
            depth -= 1

            if depth == 0:
                groups.append(''.join(current))
                current = []

    return groups
