import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

public class UserServlet extends HttpServlet {
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username");

        // Use a PreparedStatement with bind parameters so the database treats input as data, not SQL.
        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "dbuser", "dbpass");
             PreparedStatement ps = conn.prepareStatement("SELECT * FROM users WHERE username = ?")) {
            ps.setString(1, username);
            ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                resp.getWriter().println("User found: " + rs.getString("username"));
            } else {
                resp.getWriter().println("User not found");
            }
        } catch (Exception e) {
            resp.sendError(500, "Database error");
        }
    }
}
